// Verifica la llamada del servicio (firma HMAC con la clave del sentido saliente, marca de tiempo, forma y plantilla) ANTES de actuar: sin esto el webhook sería un relé abierto de WhatsApp (NOT-12).
// Las plantillas van aquí, versionadas con el flujo: el texto se cambia editándolo y el servicio no se modifica (NOT-10). Cada una declara los campos que admite; un campo fuera de la lista se rechaza (NOT-07).
const crypto = require('crypto');
const PLANTILLAS = {
  'pedido-confirmado': { version: 1, campos: ['numeroDePedido', 'nombre'], texto: '{saludo}, recibimos tu pedido {numeroDePedido}. Te avisaremos cuando avance. — BabelHub' },
  'pedido-estado': { version: 1, campos: ['numeroDePedido', 'estado'], texto: 'Tu pedido {numeroDePedido} cambió de estado: {estado}. — BabelHub' },
  'pedido-estado-sucursal': { version: 1, campos: ['numeroDePedido', 'estado'], texto: 'Pedido {numeroDePedido}: estado {estado}. — BabelHub' },
  'pedido-en-preparacion': { version: 1, campos: ['numeroDePedido', 'nombre'], texto: '{saludo}, tu pedido {numeroDePedido} está en preparación. — BabelHub' },
  'pedido-en-transito': { version: 1, campos: ['numeroDePedido', 'nombre'], texto: '{saludo}, tu pedido {numeroDePedido} va en tránsito. — BabelHub' },
  'pedido-listo-para-recojo': { version: 1, campos: ['numeroDePedido', 'nombre', 'sucursal'], texto: '{saludo}, tu pedido {numeroDePedido} está listo para recoger{enSucursal}. — BabelHub' },
  'pedido-entregado': { version: 1, campos: ['numeroDePedido', 'nombre'], texto: '{saludo}, tu pedido {numeroDePedido} fue entregado. Gracias por leer con nosotros. — BabelHub' },
  'pedido-no-recogido': { version: 1, campos: ['numeroDePedido', 'nombre'], texto: '{saludo}, tu pedido {numeroDePedido} no fue recogido a tiempo. Escríbenos si aún lo quieres. — BabelHub' },
  'pago-pendiente': { version: 1, campos: ['numeroDePedido', 'nombre'], texto: '{saludo}, el pago de tu pedido {numeroDePedido} sigue pendiente de confirmación. — BabelHub' },
  'pago-resultado': { version: 1, campos: ['numeroDePedido', 'resultado', 'nombre'], texto: '{saludo}, el pago de tu pedido {numeroDePedido} fue {resultado}. — BabelHub' },
  'pedido-anulado': { version: 1, campos: ['numeroDePedido', 'motivo', 'nombre'], texto: '{saludo}, tu pedido {numeroDePedido} fue {motivo}. — BabelHub' },
  'reembolso-automatico': { version: 1, campos: ['numeroDePedido', 'nombre'], texto: '{saludo}, iniciamos el reembolso de tu pedido {numeroDePedido}. — BabelHub' },
  'envio-guia': { version: 1, campos: ['numeroDePedido', 'numeroDeGuia', 'estado', 'nombre'], texto: '{saludo}, tu pedido {numeroDePedido} tiene la guía {numeroDeGuia} (estado: {estado}). — BabelHub' },
  'libro-digital-disponible': { version: 1, campos: ['numeroDePedido', 'nombre'], texto: '{saludo}, tu libro digital del pedido {numeroDePedido} ya está disponible en tu biblioteca. — BabelHub' },
  'devolucion-estado': { version: 1, campos: ['devolucionId', 'estado', 'nombre'], texto: '{saludo}, tu devolución {devolucionId} está en estado: {estado}. — BabelHub' },
  'traslado-cambio-de-estado': { version: 1, campos: ['numeroDeTraslado', 'estado', 'rolDeLaSucursal', 'cantidad'], texto: 'Traslado {numeroDeTraslado}: estado {estado}. Cantidad: {cantidad}. — BabelHub' }
};
// FIN-PLANTILLAS
const RUTA = '/webhook/babelhub-avisos';
const rechazar = (status) => [{ json: { valido: false, status } }];
const entrada = $input.first();
const cabeceras = entrada.json.headers || {};
const marca = String(cabeceras['x-babelhub-marca'] || '');
const firma = String(cabeceras['x-babelhub-firma'] || '');
const clave = $env.BABELHUB_FIRMA_DE_AVISOS || '';
if (clave.length < 32) { return rechazar(401); }
const crudo = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const esperada = crypto.createHmac('sha256', clave).update(marca + '.POST.' + RUTA + '.' + crudo).digest('hex');
if (firma.length !== esperada.length || !crypto.timingSafeEqual(Buffer.from(firma), Buffer.from(esperada))) { return rechazar(401); }
const marcaNumerica = Number(marca);
if (!Number.isFinite(marcaNumerica) || Math.abs(Date.now() / 1000 - marcaNumerica) > 300) { return rechazar(401); }
let cuerpo;
try { cuerpo = JSON.parse(crudo); } catch (e) { return rechazar(400); }
const plantilla = PLANTILLAS[cuerpo.plantilla];
const esId = typeof cuerpo.avisoId === 'string' && cuerpo.avisoId.length === 36 && /^[0-9a-f-]+$/.test(cuerpo.avisoId);
const esNumero = typeof cuerpo.numero === 'string' && /^[+][1-9][0-9]{7,14}$/.test(cuerpo.numero);
const campos = cuerpo.campos && typeof cuerpo.campos === 'object' && !Array.isArray(cuerpo.campos) ? cuerpo.campos : null;
if (!plantilla || !esId || !esNumero || !campos) { return rechazar(400); }
for (const [nombre, valor] of Object.entries(campos)) {
  if (!plantilla.campos.includes(nombre) || typeof valor !== 'string' || valor.length > 64) { return rechazar(400); }
  if (/[:@]|[0-9]{13,}/.test(valor)) { return rechazar(400); }
}
// Un avisoId ya entregado no se vuelve a enviar: responde duplicado y vuelve a emitir el estado. Se guarda solo el identificador (nunca el número), 48 horas como mínimo.
const datos = $getWorkflowStaticData('global');
datos.entregados = datos.entregados || {};
const limite = Date.now() - 48 * 3600 * 1000;
for (const id of Object.keys(datos.entregados)) { if (datos.entregados[id] < limite) { delete datos.entregados[id]; } }
const duplicado = Boolean(datos.entregados[cuerpo.avisoId]);
return [{ json: { valido: true, duplicado, avisoId: cuerpo.avisoId, numero: cuerpo.numero, campos, texto: plantilla.texto } }];

// Un duplicado vuelve a emitir el estado entregado (el servicio pudo no haberlo recibido).
const aviso = $('Verificar').first().json;
return [{ json: { avisoId: aviso.avisoId, estado: 'entregado' } }];

// Arma el mensaje con la plantilla: {campo} se reemplaza por su valor; {saludo} y {enSucursal} se derivan de los campos opcionales. El texto nunca lleva enlaces ni datos de pago.
const aviso = $('Verificar').first().json;
const campos = aviso.campos;
const derivados = { saludo: campos.nombre ? 'Hola ' + campos.nombre : 'Hola', enSucursal: campos.sucursal ? ' en la sucursal ' + campos.sucursal : '' };
const texto = aviso.texto.replace(/[{]([A-Za-z]+)[}]/g, (parte, nombre) => (nombre in derivados ? derivados[nombre] : (campos[nombre] || '')));
return [{ json: { avisoId: aviso.avisoId, numero: aviso.numero, texto } }];

// Evolution entregó (sin error) o falló. Solo si entregó se recuerda el avisoId (48 horas, sin el número): un reintento tras un fallo SÍ se envía de nuevo.
const base = $('Armar mensaje').first().json;
const entregado = !$json.error;
if (entregado) {
  const datos = $getWorkflowStaticData('global');
  datos.entregados = datos.entregados || {};
  datos.entregados[base.avisoId] = Date.now();
}
return [{ json: { avisoId: base.avisoId, estado: entregado ? 'entregado' : 'fallido' } }];

// Firma el estado de entrega con la clave del sentido ENTRANTE (distinta de la que firma la llamada del servicio): HMAC sobre marca.cuerpo, en hexadecimal con el prefijo sha256=.
const crypto = require('crypto');
const cuerpo = JSON.stringify({ avisoId: $json.avisoId, estado: $json.estado });
const marca = String(Math.floor(Date.now() / 1000));
const firma = 'sha256=' + crypto.createHmac('sha256', $env.BABELHUB_FIRMA_DE_ESTADOS || '').update(marca + '.' + cuerpo).digest('hex');
return [{ json: { cuerpo, marca, firma } }];
